const raw = $("Execute Command").item.json;
const normalized = $("Normalize Packet").item.json;
const build = $("Build Commands").item.json;

const errorText = typeof raw.error === "string" ? raw.error : "";
const errorLines = errorText.split(/\r?\n/).map((line) => line.trim()).filter((line) => line.length > 0);

let reason = "Prepare run failed";
for (const line of errorLines) {
  const lower = line.toLowerCase();
  const isNoise = lower.startsWith("command failed:") || lower.startsWith("at ") || lower.startsWith("+ ") || lower.startsWith("categoryinfo") || lower.startsWith("fullyqualifiederrorid");
  if (!isNoise) {
    reason = line;
    break;
  }
}

const runPath = build.runsRoot + "\\" + build.runId;

return [{
  json: {
    status: "failure",
    message: "Run preparation failed",
    reason,
    runId: build.runId,
    runPath,
    referenceImagePath: normalized.referenceImagePath || "",
    designNotesPath: normalized.designNotesPath || "",
    designSource: normalized.designSource || "",
    failureStage: "prepare_run",
    rawError: errorText
  }
}];
